#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

static long llabs_long(long x) {
    return x < 0 ? -x : x;
}

static long gcd_long(long a, long b) {
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    errno = 0;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    // Bad input: no conversion or leftover characters
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Detect overflow case (cannot take absolute value of LLONG_MIN)
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    long abs_a = llabs_long(a);
    long abs_b = llabs_long(b);

    // Out of allowed range (absolute value > 1,000,000)
    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Zero case
    if (abs_a == 0 || abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long g = gcd_long(abs_a, abs_b);
    long l = (abs_a / g) * abs_b;
    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
